package com.tianmu.agent.adapters.storage;

import com.tianmu.agent.core.AgentException;

/** Keys are generated by the repository, never by a model or a request path. */
final class ObjectKeys {
    private ObjectKeys() {}
    static void validate(String key) {
        if (key == null || !key.matches("[a-zA-Z0-9_-]{1,80}\\.(?:json|html)"))
            throw new AgentException("INVALID_ARGUMENTS", "Invalid object key");
    }
}
